def transpose_records(records):
    keys = []
    for record in records:
        for key in record:
            if key not in keys:
                keys.append(key)
    if not keys:
        return []
    result = []
    for key in keys:
        column = [record.get(key) for record in records]
        result.append([key, column])
    return result

